import { StrictMode, useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { createRoot } from 'react-dom/client';
import { BrowserRouter, Link, NavLink, Navigate, Route, Routes, useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { Activity, AlertTriangle, ArrowDownRight, ArrowLeft, ArrowRight, ArrowUpRight, BadgePercent, Boxes, Check, ChevronDown, ChevronRight, CircleHelp, ClipboardList, Cpu, CreditCard, Database, Download, Eye, LayoutDashboard, LifeBuoy, LogOut, Menu, Package, Plus, Search, ScrollText, Server, Settings, ShieldCheck, ShoppingBag, ShoppingCart, Store, Users, X } from 'lucide-react';
import { api, money, type Order, type Product } from './api';
import { UsernameAdminLogin as AdminLoginWithCredentials } from './admin-login';
import { PaymentSettingsPage } from './admin-payment';
import './styles.css';
import './clarity.css';

type Dashboard = { revenueCents:number; orders:number; pending:number; views:number; products:number; customers:number };
type OrderRow = { id:string; email:string; nickname:string; status:string; payment_status:string; total:string; created_at:string; items:string; ip_address?:string };
type Campaign = { id:number; name:string; description:string; discount_cents:number; minimum_cents:number; ends_at:string|null; active:number };
type Customer = { id:number; email:string|null; phone:string|null; contact:string; last_ip:string|null; nickname:string; created_at:string; last_seen:string; orders:number; spent_cents:number };
type SettingKey = 'store'|'payment'|'shipping'|'notifications'|'security';
const statusLabel:Record<string,string> = { completed:'已完成',pending_payment:'待支付',paid_pending_delivery:'待发货',cancelled:'已取消',refunded:'已退款' };
const dateText=(value?:string)=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—';
const prettyStatus=(value:string)=>statusLabel[value]||value||'—';
const paymentLabel=(value?:string)=>({alipay:'支付宝当面付',wechat:'微信 Native 扫码',demo:'本地演示支付'} as Record<string,string>)[value||'']||value||'—';

function AdminFrame({ children }: { children:ReactNode }) {
  const [open,setOpen]=useState(false); const [profile,setProfile]=useState(false); const navigate=useNavigate();
  const groups=[
    {label:'工作台',links:[['总览','/',LayoutDashboard],['订单管理','/orders',ShoppingCart],['商品管理','/products',Package],['库存卡密','/inventory',Boxes]]},
    {label:'经营分析',links:[['客户管理','/customers',Users],['营销活动','/marketing',BadgePercent],['经营报表','/reports',Activity]]},
    {label:'系统管理',links:[['日志与操作','/logs',ClipboardList],['系统信息','/system',Activity]]},
    {label:'店铺配置',links:[['店铺设置','/settings',Settings],['支付设置','/settings/payment',CreditCard],['发货设置','/settings/shipping',Download],['通知设置','/settings/notifications',LifeBuoy],['邮箱设置','/settings/mail',LifeBuoy],['短信设置','/settings/sms',LifeBuoy],['安全设置','/settings/security',ShieldCheck]]},
  ] as const;
  async function logout(){await api('/api/auth/logout',{method:'POST',body:JSON.stringify({kind:'admin'})}).catch(()=>{});navigate('/login',{replace:true});}
  return <div className="admin-app"><aside className={`admin-sidebar ${open?'sidebar-open':''}`}><Link to="/" className="admin-brand"><span className="brand-mark">闪</span><span>闪购卡券<small>MERCHANT CONSOLE</small></span><button className="icon-button sidebar-close" onClick={()=>setOpen(false)}><X/></button></Link><div className="sidebar-store"><div className="store-avatar">闪</div><div><b>闪购严选旗舰店</b><small><i/> 店铺营业中</small></div><ChevronDown size={15}/></div><nav className="admin-nav">{groups.map(group=><div className="nav-group" key={group.label}><span className="nav-caption">{group.label}</span>{group.links.map(([label,to,Icon])=><NavLink key={to} to={to} end={to==='/'} onClick={()=>setOpen(false)}><Icon size={17}/><span>{label}</span></NavLink>)}</div>)}</nav><div className="sidebar-bottom"><Link to="/" className="sidebar-help"><CircleHelp size={17}/>帮助与支持<ArrowRight size={14}/></Link><button className="admin-logout" onClick={logout}><LogOut size={17}/>退出管理后台</button></div></aside>{open&&<button aria-label="关闭导航" className="sidebar-scrim" onClick={()=>setOpen(false)}/>}
    <div className="admin-main"><header className="admin-topbar"><button className="icon-button admin-menu-button" onClick={()=>setOpen(true)} aria-label="打开导航"><Menu/></button><div className="breadcrumb"><span>闪购商家后台</span><ChevronRight size={14}/><b>经营中心</b></div><div className="topbar-right"><span className="admin-env"><i/>本地演示环境</span><button className="admin-profile" onClick={()=>setProfile(!profile)}><span className="profile-avatar">管</span><span>管理员<small>店铺主账号</small></span><ChevronDown size={14}/></button>{profile&&<div className="profile-popover"><button onClick={logout}><LogOut size={15}/>退出登录</button></div>}</div></header><main className="admin-content">{children}</main><footer className="admin-footer">闪购商家工作台 <span>·</span> 让每一次交付都清晰可见</footer></div></div>;
}

function AdminGuard(){const [allowed,setAllowed]=useState<boolean|null>(null);useEffect(()=>{let live=true;api<{admin:boolean}>('/api/auth/me').then(x=>live&&setAllowed(x.admin)).catch(()=>live&&setAllowed(false));return()=>{live=false};},[]);if(allowed===null)return <div className="admin-loading"><span className="spinner"/>正在验证商家身份…</div>;if(!allowed)return <Navigate to="/login" replace/>;return <AdminFrame><Routes><Route path="/" element={<DashboardPage/>}/><Route path="/orders" element={<OrdersPage/>}/><Route path="/orders/:id" element={<OrderPage/>}/><Route path="/products" element={<ProductsPage/>}/><Route path="/products/new" element={<ProductEditor/>}/><Route path="/products/:id/edit" element={<ProductEditor/>}/><Route path="/inventory" element={<InventoryPage/>}/><Route path="/customers" element={<CustomersPage/>}/><Route path="/marketing" element={<MarketingPage/>}/><Route path="/reports" element={<ReportsPage/>}/><Route path="/logs" element={<SystemLogsPage/>}/><Route path="/audit" element={<Navigate to="/logs" replace/>}/><Route path="/system" element={<SystemInfoPage/>}/><Route path="/settings" element={<SettingsPage section="store"/>}/><Route path="/settings/payment" element={<PaymentSettingsPage/>}/><Route path="/settings/shipping" element={<SettingsPage section="shipping"/>}/><Route path="/settings/notifications" element={<SettingsPage section="notifications"/>}/><Route path="/settings/mail" element={<NotificationSettingsPage kind="mail"/>}/><Route path="/settings/sms" element={<NotificationSettingsPage kind="sms"/>}/><Route path="/settings/security" element={<SettingsPage section="security"/>}/><Route path="*" element={<NotFound/>}/></Routes></AdminFrame>}


function Heading({eyebrow,title,desc,action}:{eyebrow?:string;title:string;desc?:string;action?:ReactNode}){return <div className="admin-heading"><div><span className="eyebrow">{eyebrow||'MERCHANT WORKSPACE'}</span><h1>{title}</h1>{desc&&<p>{desc}</p>}</div>{action&&<div className="heading-actions">{action}</div>}</div>}
function Panel({title,subtitle,action,children,className=''}:{title:string;subtitle?:string;action?:ReactNode;children:ReactNode;className?:string}){return <section className={`admin-panel ${className}`}><div className="panel-heading"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>{children}</section>}
function Loading(){return <div className="table-loading"><span className="spinner"/>加载中…</div>}
function ErrorBanner({children}:{children:string}){return children?<div className="admin-error"><AlertTriangle size={16}/>{children}</div>:null}
function Empty({children='暂无数据'}:{children?:string}){return <div className="admin-empty"><Package size={24}/><b>{children}</b></div>}

function DashboardPage(){const [data,setData]=useState<Dashboard|null>(null);const [orders,setOrders]=useState<OrderRow[]>([]);const [error,setError]=useState('');useEffect(()=>{Promise.all([api<Dashboard>('/api/admin/dashboard'),api<{orders:OrderRow[]}>('/api/admin/orders')]).then(([d,o])=>{setData(d);setOrders(o.orders.slice(0,6));}).catch(e=>setError(e.message));},[]);const stats=[['今日成交额',data?money(data.revenueCents/100):'—','较昨日','+12.8%',ArrowUpRight],['今日订单',data?.orders??'—','待处理订单',String(data?.pending??'—'),ShoppingBag],['在售商品',data?.products??'—','累计客户',data?.customers??'—',Users],['累计访问','—','数据统计','持续更新',Activity]] as const;return <><Heading title="经营总览" desc="欢迎回来，今天也来看看店铺的经营情况。" action={<Link className="button" to="/products/new"><Plus size={16}/>新增商品</Link>}/><ErrorBanner>{error}</ErrorBanner><div className="metric-grid">{stats.map(([label,value,sub,trend,Icon],i)=><article className="metric-card" key={label}><div className="metric-top"><span>{label}</span><span className={`metric-icon metric-icon-${i}`}><Icon size={18}/></span></div><strong>{value}</strong><div className="metric-foot"><span>{sub}</span><b className={i===0?'positive':''}>{trend}</b></div></article>)}</div><div className="dashboard-grid"><Panel title="最近订单" subtitle="及时跟进每一笔交易" action={<Link className="text-link" to="/orders">查看全部<ArrowRight size={14}/></Link>} className="recent-orders-panel">{orders.length?<OrderTable rows={orders} compact/>:<Empty>暂无订单</Empty>}</Panel><Panel title="快捷操作" subtitle="常用功能一键直达" className="quick-panel"><div className="quick-links"><Link to="/products/new"><span className="quick-icon violet"><Plus/></span><b>新增商品</b><small>上架新的数字权益</small><ArrowRight/></Link><Link to="/inventory"><span className="quick-icon green"><Boxes/></span><b>补充库存</b><small>导入卡密库存</small><ArrowRight/></Link><Link to="/marketing"><span className="quick-icon orange"><BadgePercent/></span><b>创建活动</b><small>设置优惠活动</small><ArrowRight/></Link></div></Panel></div><div className="dashboard-bottom"><div className="tip-banner"><span className="tip-icon"><Activity/></span><div><b>让店铺经营更轻松</b><p>完善商品库存，开启自动发货，让顾客购买后快速收到商品。</p></div><Link to="/settings/shipping">查看发货设置<ArrowRight size={14}/></Link></div></div></>}

function OrderTable({rows,compact=false}:{rows:OrderRow[];compact?:boolean}){return <div className="table-scroll"><table className="admin-table"><thead><tr><th>订单编号</th><th>客户</th><th>商品</th><th>金额</th><th>状态</th><th>下单时间</th>{!compact&&<><th>来源 IP</th><th/></>}</tr></thead><tbody>{rows.map(o=><tr key={o.id}><td><Link className="table-primary" to={`/orders/${encodeURIComponent(o.id)}`}>{o.id}</Link></td><td><span>{o.nickname||o.email}</span><small className="table-sub">{o.nickname?o.email:''}</small></td><td className="truncate-cell">{o.items||'数字商品'}</td><td className="amount-cell">{money(o.total)}</td><td><span className={`state state-${o.status}`}>{prettyStatus(o.status)}</span></td><td>{dateText(o.created_at)}</td>{!compact&&<><td><code>{o.ip_address||'—'}</code></td><td><Link className="row-open" to={`/orders/${encodeURIComponent(o.id)}`}><ChevronRight size={17}/></Link></td></>}</tr>)}</tbody></table></div>}
function OrdersPage(){const [rows,setRows]=useState<OrderRow[]>([]);const [searchParams,setSearchParams]=useSearchParams();const [query,setQuery]=useState(searchParams.get('q')||'');const [status,setStatus]=useState(searchParams.get('status')||'');const [error,setError]=useState('');const [loading,setLoading]=useState(true);useEffect(()=>{setLoading(true);const params=new URLSearchParams();if(query)params.set('q',query);if(status)params.set('status',status);setSearchParams(params,{replace:true});api<{orders:OrderRow[]}>(`/api/admin/orders?${params}`).then(x=>setRows(x.orders)).catch(e=>setError(e.message)).finally(()=>setLoading(false));},[query,status]);return <><Heading title="订单管理" desc="查看订单状态、客户信息与交付情况。"/><ErrorBanner>{error}</ErrorBanner><Panel title="全部订单" subtitle={`当前共 ${rows.length} 笔订单`}><div className="table-toolbar"><label className="admin-search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索订单号、邮箱或客户"/></label><select className="admin-select" value={status} onChange={e=>setStatus(e.target.value)}><option value="">全部状态</option><option value="pending_payment">待支付</option><option value="paid_pending_delivery">待发货</option><option value="completed">已完成</option><option value="cancelled">已取消</option><option value="refunded">已退款</option></select></div>{loading?<Loading/>:rows.length?<OrderTable rows={rows}/>:<Empty>没有找到匹配的订单</Empty>}</Panel></>}

function OrderPage(){const {id=''}=useParams();const [order,setOrder]=useState<Order|null>(null);const [error,setError]=useState('');const [codes,setCodes]=useState('');const [busy,setBusy]=useState(false);const [notice,setNotice]=useState('');const load=()=>api<{order:Order}>(`/api/admin/orders/${encodeURIComponent(id)}`).then(x=>setOrder(x.order)).catch(e=>setError(e.message));useEffect(()=>{load();},[id]);async function action(name:'deliver'|'refund'){if(!order)return;if(name==='refund'&&!confirm('确认将此订单标记为已退款？'))return;setBusy(true);setError('');try{const result=await api<{order:Order}>(`/api/admin/orders/${encodeURIComponent(id)}/${name}`,{method:'POST',body:JSON.stringify(name==='deliver'?{codes:codes.split(/\r?\n/).map(x=>x.trim()).filter(Boolean)}:{})});setOrder(result.order);setNotice(name==='deliver'?'发货完成':'已更新退款状态');}catch(e){setError((e as Error).message)}finally{setBusy(false)}}if(!order)return <><Heading title="订单详情"/><ErrorBanner>{error}</ErrorBanner><Loading/></>;const required=order.items.filter(item=>item.delivery_type==="manual").reduce((sum,item)=>sum+item.quantity,0);const codeCount=codes.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).length;return <><Heading title="订单详情" desc={`订单编号：${order.id}`} action={<Link className="button button-secondary" to="/orders"><ArrowLeft size={16}/>返回订单</Link>}/><ErrorBanner>{error}</ErrorBanner>{notice&&<div className="admin-success"><Check size={16}/>{notice}</div>}<div className="detail-admin-grid"><Panel title="订单信息" subtitle="客户及支付信息"><div className="detail-fields"><div><small>订单状态</small><span className={`state state-${order.status}`}>{prettyStatus(order.status)}</span></div><div><small>订单金额</small><b className="amount-cell">{money(order.total)}</b></div><div><small>客户联系方式</small><b>{order.contact||order.email}</b></div><div><small>来源 IP</small><b><code>{order.ipAddress||'—'}</code></b></div><div><small>支付方式</small><b>{paymentLabel(order.paymentMethod)}</b></div><div><small>创建时间</small><b>{dateText(order.createdAt)}</b></div><div><small>支付状态</small><b>{order.paymentStatus==='paid'?'已支付':'未支付'}</b></div></div></Panel><Panel title="商品明细" subtitle="订单包含的商品和数量"><div className="admin-item-list">{order.items.map((item,i)=><div className="admin-item" key={`${item.product_id}-${i}`}><span className="mini-art">✦</span><div><b>{item.product_name}</b><small>数量 × {item.quantity}</small></div><strong>{money(item.unitPrice||item.unit_price_cents/100)}</strong></div>)}</div></Panel><Panel title="交付卡密" subtitle={order.cards?.length?`共 ${order.cards.length} 条卡密`:'尚未交付'}><div className="admin-codes">{order.cards?.length?order.cards.map((code,i)=><code key={`${i}-${code}`}>{code}</code>):<p>该订单暂时没有可显示的卡密。</p>}</div>{order.status==='paid_pending_delivery'&&<div className="deliver-form"><label>手动发货卡密，每行一条（需 {required} 条）<textarea value={codes} onChange={e=>setCodes(e.target.value)} rows={Math.min(8,Math.max(3,required))} placeholder="请输入卡密，每行一条"/></label><button disabled={busy||codeCount!==required} className="button" onClick={()=>action('deliver')}>{busy?'处理中…':'确认发货'}<ArrowRight size={15}/></button><small>已填写 {codeCount} / {required} 条</small></div>}</Panel><Panel title="订单操作" subtitle="变更订单履约状态"><div className="order-actions-admin"><p>{order.status==='pending_payment'?'订单尚未支付。':order.status==='completed'?'订单已完成交付。':order.status==='refunded'?'订单已标记退款。':'你可以在这里更新订单状态。'}</p>{order.paymentStatus==='paid'&&order.status!=='refunded'&&<button className="button button-danger" disabled={busy} onClick={()=>action('refund')}>标记退款</button>}</div></Panel></div></>}

function ProductsPage(){const [products,setProducts]=useState<Product[]>([]);const [query,setQuery]=useState('');const [error,setError]=useState('');const [loading,setLoading]=useState(true);const reload=()=>api<{products:Product[]}>('/api/admin/products').then(x=>setProducts(x.products)).catch(e=>setError(e.message)).finally(()=>setLoading(false));useEffect(()=>{reload();},[]);const shown=useMemo(()=>products.filter(p=>`${p.name} ${p.category} ${p.id}`.toLowerCase().includes(query.toLowerCase())),[products,query]);async function toggle(p:Product){setError('');try{await api(`/api/admin/products/${encodeURIComponent(p.id)}`,{method:'PATCH',body:JSON.stringify({active:!p.active})});setProducts(items=>items.map(x=>x.id===p.id?{...x,active:!x.active}:x));}catch(e){setError((e as Error).message)}}return <><Heading title="商品管理" desc="管理商品信息、价格、库存展示和上架状态。" action={<Link className="button" to="/products/new"><Plus size={16}/>新增商品</Link>}/><ErrorBanner>{error}</ErrorBanner><Panel title="商品列表" subtitle={`共 ${products.length} 件商品`}><div className="table-toolbar"><label className="admin-search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索商品名称、分类或编号"/></label><span className="muted">商品数据实时同步到商城</span></div>{loading?<Loading/>:shown.length?<div className="table-scroll"><table className="admin-table"><thead><tr><th>商品</th><th>分类</th><th>售价</th><th>库存</th><th>发货方式</th><th>状态</th><th>操作</th></tr></thead><tbody>{shown.map(p=><tr key={p.id}><td><div className="product-cell"><span className="mini-art">{p.icon}</span><span><b className="table-primary">{p.name}</b><small className="table-sub">{p.id}</small></span></div></td><td>{p.category}</td><td className="amount-cell">{money(p.price)}</td><td>{p.stock}</td><td>{p.deliveryType==='card'?'自动发货':'手动发货'}</td><td><span className={`state ${p.active?'state-active':'state-inactive'}`}>{p.active?'销售中':'已下架'}</span></td><td><div className="table-actions"><Link className="small-action" to={`/products/${encodeURIComponent(p.id)}/edit`} aria-label="编辑商品"><Eye size={15}/></Link><button className="small-action" onClick={()=>toggle(p)}>{p.active?'下架':'上架'}</button></div></td></tr>)}</tbody></table></div>:<Empty>暂无商品</Empty>}</Panel></>}

function ProductEditor(){
  const {id}=useParams();const edit=Boolean(id);const navigate=useNavigate();
  const [form,setForm]=useState({id:'',name:'',category:'影音会员',description:'',icon:'✦',active:true,deliveryType:'card'});
  const [variants,setVariants]=useState<Array<{id:string;name:string;price:string;originalPrice:string;active:boolean}>>([{id:'',name:'1个月',price:'',originalPrice:'',active:true}]);
  const [error,setError]=useState('');const [busy,setBusy]=useState(false);
  useEffect(()=>{if(!id)return;api<{products:Product[]}>('/api/admin/products').then(x=>{const p=x.products.find(y=>y.id===id);if(!p){setError('商品不存在');return;}setForm({id:p.id,name:p.name,category:p.category,description:p.description,icon:p.icon,active:p.active,deliveryType:p.deliveryType});setVariants(p.variants.map(v=>({id:v.id,name:v.name,price:v.price,originalPrice:(v.originalCents/100).toFixed(2),active:v.active})));}).catch(e=>setError(e.message));},[id]);
  function field(key:string,value:string|boolean){setForm(f=>({...f,[key]:value}));}
  function variantField(index:number,key:string,value:string|boolean){setVariants(current=>current.map((v,i)=>i===index?{...v,[key]:value}:v));}
  function removeVariant(index:number){setVariants(current=>current[index].id?current.map((v,i)=>i===index?{...v,active:false}:v):current.filter((_,i)=>i!==index));}
  async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError('');try{const active=variants.filter(v=>v.active);if(!active.length)throw new Error('至少保留一个启用中的规格');if(active.some(v=>!v.name.trim()||v.price===''||Number(v.price)<0))throw new Error('请填写所有启用规格的名称和价格');const body={...form,variants:variants.map(v=>({...v,price:Number(v.price||0),originalPrice:Number(v.originalPrice||0)}))};if(edit)await api(`/api/admin/products/${encodeURIComponent(id!)}`,{method:'PATCH',body:JSON.stringify(body)});else await api('/api/admin/products',{method:'POST',body:JSON.stringify(body)});navigate('/products');}catch(e){setError((e as Error).message);}finally{setBusy(false)}}
  return <><Heading title={edit?'编辑商品':'新增商品'} desc="为一个商品设置多个可购买规格，例如 1 个月、3 个月或不同面额。" action={<Link className="button button-secondary" to="/products"><ArrowLeft size={16}/>返回列表</Link>}/><ErrorBanner>{error}</ErrorBanner><form className="editor-grid" onSubmit={submit}>
    <Panel title="基本信息" subtitle="商品名称和说明展示在商城前台"><div className="form-grid"><label>商品名称<input required maxLength={100} value={form.name} onChange={e=>field('name',e.target.value)} placeholder="例如：影音平台会员"/></label><label>商品编号<input required disabled={edit} value={form.id} onChange={e=>field('id',e.target.value)} placeholder="例如：video-vip"/></label><label>商品分类<select value={form.category} onChange={e=>field('category',e.target.value)}>{['影音会员','游戏充值','软件服务','生活权益','其他'].map(v=><option key={v}>{v}</option>)}</select></label><label>商品图标<input maxLength={4} value={form.icon} onChange={e=>field('icon',e.target.value)} placeholder="✦"/></label><label className="full-field">商品描述<textarea rows={4} value={form.description} onChange={e=>field('description',e.target.value)} placeholder="介绍商品权益、使用方式和注意事项"/></label></div></Panel>
    <Panel title="商品规格" subtitle="每个规格拥有独立价格、库存和卡密池" action={<button type="button" className="button button-secondary" onClick={()=>setVariants(v=>[...v,{id:'',name:'',price:'',originalPrice:'',active:true}])}><Plus size={15}/>添加规格</button>}>
      <div className="variant-editor-list">{variants.map((v,index)=><div className={`variant-editor-row ${v.active?'':'variant-disabled'}`} key={v.id||`new-${index}`}><div className="variant-editor-fields"><label>规格名称<input required={v.active} disabled={!v.active} value={v.name} onChange={e=>variantField(index,'name',e.target.value)} placeholder="例如：3 个月"/></label><label>售价（元）<input required={v.active} disabled={!v.active} type="number" min="0" step="0.01" value={v.price} onChange={e=>variantField(index,'price',e.target.value)}/></label><label>划线价（元）<input disabled={!v.active} type="number" min="0" step="0.01" value={v.originalPrice} onChange={e=>variantField(index,'originalPrice',e.target.value)}/></label></div><div className="variant-editor-actions"><label className="variant-active-toggle"><input type="checkbox" checked={v.active} onChange={e=>variantField(index,'active',e.target.checked)}/>前台可售</label><button type="button" className="small-action" onClick={()=>removeVariant(index)}>{v.id?'停用':'移除'}</button></div></div>)}</div>
    </Panel>
    <Panel title="交付方式" subtitle="自动发货会按规格从对应卡密池扣库存"><div className="form-grid"><label>发货方式<select value={form.deliveryType} onChange={e=>field('deliveryType',e.target.value)}><option value="card">自动卡密发货</option><option value="manual">商家手动发货</option></select></label><label className="switch-field"><span><b>上架销售</b><small>开启后顾客可在前台购买</small></span><input type="checkbox" checked={form.active} onChange={e=>field('active',e.target.checked)}/></label></div></Panel>
    <div className="editor-actions"><button type="button" className="button button-secondary" onClick={()=>navigate('/products')}>取消</button><button className="button" disabled={busy}>{busy?'正在保存…':'保存商品'}<Check size={16}/></button></div>
  </form></>;
}

function InventoryPage(){
  type InventoryRow={id:string;name:string;variant_id:string;variant_name:string;available:number;reserved:number;sold:number};
  const [data,setData]=useState<InventoryRow[]>([]);const [products,setProducts]=useState<Product[]>([]);const [productId,setProductId]=useState('');const [variantId,setVariantId]=useState('');
  const [codes,setCodes]=useState('');const [error,setError]=useState('');const [message,setMessage]=useState('');const [busy,setBusy]=useState(false);
  const reload=()=>Promise.all([api<{inventory:InventoryRow[]}>('/api/admin/inventory'),api<{products:Product[]}>('/api/admin/products')]).then(([a,p])=>{setData(a.inventory);setProducts(p.products);if(!productId&&p.products.length){setProductId(p.products[0].id);setVariantId(p.products[0].variants.find(v=>v.active)?.id||'');}}).catch(e=>setError(e.message));
  useEffect(()=>{reload();},[]);const selected=products.find(p=>p.id===productId);const activeVariants=selected?.variants.filter(v=>v.active)||[];
  useEffect(()=>{if(activeVariants.length&&!activeVariants.some(v=>v.id===variantId))setVariantId(activeVariants[0].id);},[productId,products]);
  const count=codes.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).length;
  async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError('');setMessage('');try{const result=await api<{added:number;duplicates:number}>('/api/admin/inventory/import',{method:'POST',body:JSON.stringify({productId,variantId,codes})});setMessage(`成功导入 ${result.added} 条，跳过重复 ${result.duplicates} 条。`);setCodes('');await reload();}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  return <><Heading title="库存卡密" desc="每个商品规格分别管理库存。导入时先选商品，再选对应规格。"/><ErrorBanner>{error}</ErrorBanner>{message&&<div className="admin-success"><Check size={16}/>{message}</div>}<div className="inventory-grid">
    <Panel title="规格库存" subtitle="付款中的订单会暂时锁定对应卡密"><div className="table-scroll"><table className="admin-table"><thead><tr><th>商品与规格</th><th>可用库存</th><th>付款锁定</th><th>已售出</th><th>状态</th></tr></thead><tbody>{data.map(x=><tr key={x.variant_id}><td><b>{x.name}</b><small className="table-sub">{x.variant_name}</small></td><td><b className={Number(x.available)<10?'low-stock':''}>{x.available}</b></td><td>{x.reserved||0}</td><td>{x.sold}</td><td><span className={`state ${Number(x.available)||Number(x.reserved)?'state-active':'state-inactive'}`}>{Number(x.reserved)?`付款中锁定 ${x.reserved} 条`:Number(x.available)?'库存充足':'库存不足'}</span></td></tr>)}</tbody></table></div></Panel>
    <Panel title="批量导入卡密" subtitle="每行一条；规格之间库存独立，重复卡密会自动跳过"><form className="import-form" onSubmit={submit}><label>选择商品<select required value={productId} onChange={e=>{const next=products.find(p=>p.id===e.target.value);setProductId(e.target.value);setVariantId(next?.variants.find(v=>v.active)?.id||'');}}>{products.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label>选择规格<select required value={variantId} onChange={e=>setVariantId(e.target.value)}>{activeVariants.map(v=><option key={v.id} value={v.id}>{v.name} · {money(v.priceCents/100)}</option>)}</select></label><label>卡密内容<textarea rows={12} value={codes} onChange={e=>setCodes(e.target.value)} placeholder={'XXXX-XXXX-XXXX\nYYYY-YYYY-YYYY\n每行输入一条卡密'}/></label><div className="import-count"><span>已识别 <b>{count}</b> 条</span><small>单次最多 10,000 条</small></div><button className="button full-button" disabled={busy||!count||!variantId}>{busy?'正在导入…':'导入此规格库存'}<ArrowRight size={15}/></button></form></Panel>
  </div></>;
}

function CustomersPage(){const [rows,setRows]=useState<Customer[]>([]);const [query,setQuery]=useState('');const [error,setError]=useState('');const [loading,setLoading]=useState(true);useEffect(()=>{setLoading(true);api<{customers:Customer[]}>(`/api/admin/customers?q=${encodeURIComponent(query)}`).then(x=>setRows(x.customers)).catch(e=>setError(e.message)).finally(()=>setLoading(false));},[query]);return <><Heading title="客户管理" desc="了解客户下单情况与消费表现，提供更贴心的服务。"/><ErrorBanner>{error}</ErrorBanner><Panel title="客户列表" subtitle={`当前匹配 ${rows.length} 位客户`}><div className="table-toolbar"><label className="admin-search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索邮箱、手机号或昵称"/></label><span className="muted">客户隐私信息仅用于订单服务</span></div>{loading?<Loading/>:rows.length?<div className="table-scroll"><table className="admin-table"><thead><tr><th>客户</th><th>来源 IP</th><th>注册时间</th><th>最近活跃</th><th>订单数</th><th>累计消费</th><th/></tr></thead><tbody>{rows.map(c=><tr key={c.id}><td><div className="customer-cell"><span className="profile-avatar">{c.nickname?.slice(0,1)||'客'}</span><span><b>{c.nickname||'新客户'}</b><small className="table-sub">{c.contact||'—'}</small></span></div></td><td><code>{c.last_ip||'—'}</code></td><td>{dateText(c.created_at)}</td><td>{dateText(c.last_seen)}</td><td>{c.orders}</td><td className="amount-cell">{money(Number(c.spent_cents)/100)}</td><td><Link className="row-open" to={`/orders?q=${encodeURIComponent(c.contact||'')}`}><ChevronRight size={17}/></Link></td></tr>)}</tbody></table></div>:<Empty>还没有客户记录</Empty>}</Panel></>}
function MarketingPage(){const [rows,setRows]=useState<Campaign[]>([]);const [error,setError]=useState('');const [notice,setNotice]=useState('');const [show,setShow]=useState(false);const [busy,setBusy]=useState(false);const [form,setForm]=useState({name:'',description:'',discount:'5',minimum:'0',endsAt:''});const reload=()=>api<{campaigns:Campaign[]}>('/api/admin/campaigns').then(x=>setRows(x.campaigns)).catch(e=>setError(e.message));useEffect(()=>{reload();},[]);async function create(e:FormEvent){e.preventDefault();setBusy(true);setError('');try{await api('/api/admin/campaigns',{method:'POST',body:JSON.stringify({...form,discount:Number(form.discount),minimum:Number(form.minimum),endsAt:form.endsAt||null,active:true})});setNotice('优惠活动已创建');setShow(false);setForm({name:'',description:'',discount:'5',minimum:'0',endsAt:''});await reload();}catch(e){setError((e as Error).message)}finally{setBusy(false)}}async function toggle(c:Campaign){try{await api(`/api/admin/campaigns/${c.id}`,{method:'PATCH',body:JSON.stringify({active:!c.active})});setRows(items=>items.map(x=>x.id===c.id?{...x,active:x.active?0:1}:x));}catch(e){setError((e as Error).message)}}return <><Heading title="营销活动" desc="创建优惠活动，给新客带来更好的首次购买体验。" action={<button className="button" onClick={()=>setShow(!show)}><Plus size={16}/>创建活动</button>}/><ErrorBanner>{error}</ErrorBanner>{notice&&<div className="admin-success"><Check size={16}/>{notice}</div>}{show&&<Panel title="创建优惠活动" subtitle="活动创建后会自动参与新客首单优惠计算"><form className="form-grid campaign-form" onSubmit={create}><label>活动名称<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="例如：新客首单优惠"/></label><label>优惠金额（元）<input required min="0" step="0.01" type="number" value={form.discount} onChange={e=>setForm({...form,discount:e.target.value})}/></label><label>最低消费（元）<input min="0" step="0.01" type="number" value={form.minimum} onChange={e=>setForm({...form,minimum:e.target.value})}/></label><label>结束日期<input type="date" value={form.endsAt} onChange={e=>setForm({...form,endsAt:e.target.value})}/></label><label className="full-field">活动说明<textarea rows={2} value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><div className="editor-actions"><button type="button" className="button button-secondary" onClick={()=>setShow(false)}>取消</button><button className="button" disabled={busy}>{busy?'正在创建…':'创建活动'}</button></div></form></Panel>}<div className="campaign-grid">{rows.map(c=><article className="campaign-card" key={c.id}><div className="campaign-top"><span className="campaign-icon"><BadgePercent/></span><span className={`state ${c.active?'state-active':'state-inactive'}`}>{c.active?'进行中':'已暂停'}</span></div><h2>{c.name}</h2><p>{c.description||'优惠活动'}</p><strong>¥{(c.discount_cents/100).toFixed(2)}<small> 首单优惠</small></strong><div className="campaign-meta"><span>最低消费 ¥{(c.minimum_cents/100).toFixed(2)}</span><span>{c.ends_at?`截止 ${new Date(c.ends_at).toLocaleDateString('zh-CN')}`:'长期有效'}</span></div><button className="button button-secondary full-button" onClick={()=>toggle(c)}>{c.active?'暂停活动':'重新启用'}</button></article>)}{!rows.length&&<div className="admin-panel"><Empty>还没有营销活动</Empty></div>}</div></>}

function ReportsPage(){const [daily,setDaily]=useState<Array<{day:string;orders:number;revenue_cents:number}>>([]);const [categories,setCategories]=useState<Array<{category:string;orders:number;revenue_cents:number}>>([]);const [error,setError]=useState('');useEffect(()=>{api<{daily:typeof daily;categories:Array<{category:string;orders:number;revenue_cents:number}>}>('/api/admin/reports').then(x=>{setDaily(x.daily);setCategories(x.categories)}).catch(e=>setError(e.message));},[]);const max=Math.max(1,...daily.map(x=>Number(x.revenue_cents)));return <><Heading title="经营报表" desc="近 30 天订单趋势与商品分类表现。"/><ErrorBanner>{error}</ErrorBanner><div className="report-metrics"><article className="report-summary"><span>统计周期</span><b>近 30 天</b><small>按订单创建日期汇总</small></article><article className="report-summary"><span>订单总量</span><b>{daily.reduce((n,x)=>n+Number(x.orders),0)}</b><small>包含未支付订单</small></article><article className="report-summary"><span>成交总额</span><b>{money(daily.reduce((n,x)=>n+Number(x.revenue_cents),0)/100)}</b><small>仅统计已支付订单</small></article></div><div className="reports-grid"><Panel title="每日成交趋势" subtitle="近 30 天成交金额"><div className="chart-area">{daily.length?daily.map(x=><div className="chart-column" key={String(x.day)} title={`${new Date(x.day).toLocaleDateString('zh-CN')} · ${money(Number(x.revenue_cents)/100)}`}><div className="chart-bar" style={{height:`${Math.max(4,Number(x.revenue_cents)/max*100)}%`}}/><small>{new Date(x.day).getDate()}</small></div>):<Empty>暂无成交数据</Empty>}</div><div className="chart-legend"><i/>每日成交额</div></Panel><Panel title="分类表现" subtitle="不同商品分类的成交贡献"><div className="category-report">{categories.length?categories.map(x=><div className="category-report-row" key={x.category}><span className="category-dot"/><div><b>{x.category}</b><small>{x.orders} 笔订单</small></div><strong>{money(Number(x.revenue_cents)/100)}</strong></div>):<Empty>暂无分类数据</Empty>}</div></Panel></div></>}

const settingsLinks:Array<[string,string]>=[['基本信息','/settings'],['支付设置','/settings/payment'],['发货设置','/settings/shipping'],['通知设置','/settings/notifications'],['邮箱设置','/settings/mail'],['短信设置','/settings/sms'],['安全设置','/settings/security']];
const settingMeta:Record<SettingKey,{title:string;desc:string;links:Array<[string,string]>}>= {
  store:{title:'店铺设置',desc:'维护店铺展示信息与营业状态。',links:settingsLinks},
  payment:{title:'支付设置',desc:'配置可用支付方式与订单支付规则。',links:settingsLinks},
  shipping:{title:'发货设置',desc:'设置自动发货策略与库存提醒。',links:settingsLinks},
  notifications:{title:'通知设置',desc:'选择重要订单事件的通知方式。',links:settingsLinks},
  security:{title:'安全设置',desc:'管理后台账户与基础安全策略。',links:settingsLinks},
};
function SystemLogsPage(){
  type Log={id:string;source:string;actor:string;action:string;target_type:string;target_id:string;details:unknown;ip:string;level:string;created_at:string};
  const [rows,setRows]=useState<Log[]>([]);const [level,setLevel]=useState('');const [kind,setKind]=useState('');const [query,setQuery]=useState('');const [error,setError]=useState('');const [loading,setLoading]=useState(true);
  useEffect(()=>{const params=new URLSearchParams();if(level)params.set('level',level);if(kind)params.set('kind',kind);if(query)params.set('q',query);setLoading(true);api<{logs:Log[]}>(`/api/admin/logs?${params}`).then(x=>setRows(x.logs)).catch(e=>setError(e.message)).finally(()=>setLoading(false));},[level,kind,query]);
  return <><Heading title="日志与操作" desc="在一个时间线上查看顾客行为、管理员操作和系统事件，并核对来源 IP。"/><ErrorBanner>{error}</ErrorBanner><Panel title="统一事件记录" subtitle={`最近 ${rows.length} 条记录，最多显示 500 条`}><div className="table-toolbar"><label className="admin-search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索操作人、事件、订单或 IP"/></label><select className="admin-select" value={kind} onChange={e=>setKind(e.target.value)}><option value="">全部记录</option><option value="顾客操作">顾客操作</option><option value="管理员操作">管理员操作</option><option value="系统事件">系统事件</option></select><select className="admin-select" value={level} onChange={e=>setLevel(e.target.value)}><option value="">全部级别</option><option value="info">信息</option><option value="warn">警告</option><option value="error">错误</option></select></div>{loading?<Loading/>:rows.length?<div className="table-scroll"><table className="admin-table"><thead><tr><th>时间</th><th>类型</th><th>操作人</th><th>事件</th><th>目标</th><th>IP 地址</th><th>详情</th></tr></thead><tbody>{rows.map(row=><tr key={row.id}><td>{dateText(row.created_at)}</td><td><span className={`state ${row.level==='error'?'log-error':row.level==='warn'?'log-warn':'log-info'}`}>{row.source}</span></td><td>{row.actor||'—'}</td><td>{row.action}</td><td>{row.target_type||'—'}{row.target_id?` · ${row.target_id}`:''}</td><td><code>{row.ip||'—'}</code></td><td><code className="log-details">{JSON.stringify(row.details||{})}</code></td></tr>)}</tbody></table></div>:<Empty>暂无匹配的记录</Empty>}</Panel></>;
}

type SystemInfo={capturedAt:string;runtime:{node:string;platform:string;hostname:string;uptimeSeconds:number;startedAt:string};system:{cpuCount:number;loadAverage:number[];totalMemoryBytes:number;freeMemoryBytes:number;usedMemoryBytes:number};process:{rssBytes:number;heapUsedBytes:number;heapTotalBytes:number;externalBytes:number};database:{connected:boolean;name:string;version:string;size:string;error?:string};pool:{total:number;idle:number;waiting:number}};
const bytesText=(value:number)=>`${(Number(value||0)/1024/1024).toFixed(1)} MB`;
const uptimeText=(value:number)=>{const seconds=Math.max(0,Number(value)||0),days=Math.floor(seconds/86400),hours=Math.floor(seconds%86400/3600),minutes=Math.floor(seconds%3600/60);return `${days?`${days} 天 `:''}${hours} 小时 ${minutes} 分钟`};
function SystemInfoPage(){const [data,setData]=useState<SystemInfo|null>(null);const [error,setError]=useState('');const [loading,setLoading]=useState(true);const [updatedAt,setUpdatedAt]=useState('');const refresh=()=>api<SystemInfo>('/api/admin/system-info').then(info=>{setData(info);setUpdatedAt(new Date().toLocaleTimeString('zh-CN',{hour12:false}));setError('')}).catch(e=>setError(e.message)).finally(()=>setLoading(false));useEffect(()=>{refresh();const timer=window.setInterval(refresh,10000);return()=>window.clearInterval(timer)},[]);return <><Heading title="系统信息" desc="查看服务运行时长、内存使用、数据库状态和连接池情况。" action={<button className="button button-secondary" onClick={refresh}><Activity size={16}/>立即刷新</button>}/><ErrorBanner>{error}</ErrorBanner>{loading&&!data?<Loading/>:data&&<><div className="system-info-grid"><article className="system-info-card"><span className="system-info-icon"><Server size={18}/></span><small>服务运行</small><strong>{uptimeText(data.runtime.uptimeSeconds)}</strong><p>{data.runtime.node} · {data.runtime.platform}</p></article><article className="system-info-card"><span className="system-info-icon"><Cpu size={18}/></span><small>系统内存</small><strong>{bytesText(data.system.usedMemoryBytes)} / {bytesText(data.system.totalMemoryBytes)}</strong><div className="system-memory-track"><i style={{width:`${Math.min(100,Math.max(0,data.system.usedMemoryBytes/data.system.totalMemoryBytes*100))}%`}}/></div><p>{data.system.cpuCount} 个 CPU 核心 · 负载 {data.system.loadAverage.map(x=>Number(x).toFixed(2)).join(' / ')}</p></article><article className="system-info-card"><span className="system-info-icon"><Activity size={18}/></span><small>Node 进程内存</small><strong>{bytesText(data.process.rssBytes)}</strong><p>堆内存 {bytesText(data.process.heapUsedBytes)} / {bytesText(data.process.heapTotalBytes)} · 外部 {bytesText(data.process.externalBytes)}</p></article><article className="system-info-card"><span className="system-info-icon"><Database size={18}/></span><small>PostgreSQL 数据库</small><strong><i className={data.database.connected?'system-dot-ok':'system-dot-error'}/>{data.database.connected?'连接正常':'连接异常'}</strong><p>{data.database.connected?`${data.database.name} · 占用 ${data.database.size}`:data.database.error}</p></article></div><div className="system-info-columns"><Panel title="服务实例" subtitle="当前运行环境"><div className="system-info-list"><div><span>主机名</span><b>{data.runtime.hostname}</b></div><div><span>启动时间</span><b>{dateText(data.runtime.startedAt)}</b></div><div><span>最近刷新</span><b>{updatedAt||dateText(data.capturedAt)}</b></div><div><span>空闲系统内存</span><b>{bytesText(data.system.freeMemoryBytes)}</b></div></div></Panel><Panel title="数据库连接池" subtitle="当前 PostgreSQL 请求连接情况"><div className="system-info-list"><div><span>数据库</span><b>{data.database.name||'—'}</b></div><div><span>数据库大小</span><b>{data.database.size||'—'}</b></div><div><span>活跃连接</span><b>{data.pool.total-data.pool.idle}</b></div><div><span>空闲连接 / 等待数</span><b>{data.pool.idle} / {data.pool.waiting}</b></div></div>{data.database.version&&<p className="system-db-version">{data.database.version}</p>}</Panel></div><p className="system-info-footnote">页面每 10 秒自动刷新。Windows 环境的系统负载值由运行时返回，可能为 0。</p></>}</>}
function NotificationSettingsPage({kind}:{kind:'mail'|'sms'}){const isMail=kind==='mail';const title=isMail?'邮箱设置':'短信设置';const [data,setData]=useState<Record<string,any>>({});const [ready,setReady]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);const load=()=>Promise.all([api<{settings:Record<string,any>}>(`/api/admin/settings/${kind}`),api<{mailReady:boolean;smsReady:boolean}>('/api/admin/notification-status')]).then(([x,status])=>{setData(x.settings||{});setReady(isMail?status.mailReady:status.smsReady)}).catch(e=>setError(e.message)).finally(()=>setLoading(false));useEffect(()=>{load()},[kind]);function change(key:string,value:any){setData(x=>({...x,[key]:value}))}async function save(e:FormEvent){e.preventDefault();setBusy(true);setError('');setNotice('');try{await api(`/api/admin/settings/${kind}`,{method:'PUT',body:JSON.stringify(data)});setNotice('设置已保存');await load()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}return <><Heading title={title} desc={isMail?'订单填写邮箱时发送订单通知；生产环境开启 SMTP 后，也可用于账户验证码登录。购买本身不验证邮箱。':'订单填写手机号时发送订单通知；开启短信服务并设置登录模板后，也可用于账户验证码登录。购买本身不验证手机号。'}/><ErrorBanner>{error}</ErrorBanner>{notice&&<div className="admin-success"><Check size={16}/>{notice}</div>}<Panel title={isMail?'SMTP 邮件通道':'短信服务通道'} subtitle={ready?'服务凭据已就绪':'还需要补充服务凭据'}><div className={`settings-callout ${ready?'notice-ready':'notice-pending'}`}><ShieldCheck/><div><b>{ready?'发送服务已就绪':'仅保存配置，尚不能实际发送'}</b><p>{isMail?'SMTP 密码通过服务端环境变量 SMTP_PASSWORD 配置，避免密码明文存入数据库。':'短信密钥通过服务端环境变量 SMS_API_TOKEN 配置；接口接收标准 JSON 订单通知。'}</p></div></div><form className="settings-form" onSubmit={save}>{isMail?<><Toggle label="启用邮件服务" hint="订单完成后发送订单与卡密；生产环境开启 SMTP 后也用于账户验证码登录。下单无需验证邮箱。" checked={Boolean(data.enabled)} onChange={v=>change('enabled',v)}/><label>SMTP 服务器<input value={data.host||''} onChange={e=>change('host',e.target.value)} placeholder="smtp.example.com"/></label><div className="form-grid"><label>SMTP 端口<input type="number" min="1" max="65535" value={data.port??587} onChange={e=>change('port',Number(e.target.value))}/></label><label className="switch-row"><span><b>使用 SSL/TLS</b><small>通常 465 端口启用，587 端口关闭</small></span><input type="checkbox" checked={Boolean(data.secure)} onChange={e=>change('secure',e.target.checked)}/></label></div><label>SMTP 用户名<input autoComplete="off" value={data.username||''} onChange={e=>change('username',e.target.value)} placeholder="邮箱账号或 SMTP 用户名"/></label><label>发件邮箱<input type="email" value={data.fromAddress||''} onChange={e=>change('fromAddress',e.target.value)} placeholder="service@example.com"/></label><label>邮件显示名称<input value={data.fromName||''} onChange={e=>change('fromName',e.target.value)}/></label><label>邮件标题<input value={data.subject||''} onChange={e=>change('subject',e.target.value)}/></label><p className="form-hint">请在服务端 .env 中设置 SMTP_PASSWORD；保存后重启服务。生产环境登录验证码会发送到邮箱；开发环境会显示本地演示验证码。</p></>:<><Toggle label="启用短信服务" hint="可用于订单通知；配置登录验证码模板后，也可用于账户注册和登录。" checked={Boolean(data.enabled)} onChange={v=>change('enabled',v)}/><label>短信 API 地址<input type="url" value={data.endpoint||''} onChange={e=>change('endpoint',e.target.value)} placeholder="https://sms-gateway.example/api/messages"/></label><label>短信签名<input value={data.signName||''} onChange={e=>change('signName',e.target.value)} placeholder="已在服务商备案的短信签名"/></label><label>订单通知模板编号<input value={data.templateId||''} onChange={e=>change('templateId',e.target.value)} placeholder="服务商订单模板 ID"/></label><label>登录验证码模板编号<input value={data.loginTemplateId||''} onChange={e=>change('loginTemplateId',e.target.value)} placeholder="需要填写支持验证码变量的模板 ID"/></label><div className="settings-callout"><LifeBuoy/><div><b>短信接口格式</b><p>服务端会向此地址 POST JSON：to、phone、signName、templateId、code、message；使用 Bearer Token 授权。登录验证码模板需支持 code 变量。</p></div></div><p className="form-hint">请在服务端 .env 中设置 SMS_API_TOKEN；需要服务商提供可用的短信签名、模板和 API 地址。</p></>}<div className="settings-actions"><button className="button" disabled={busy}>{busy?'保存中…':'保存设置'}<Check size={15}/></button></div></form></Panel></>}
function AdminAccountPanel(){
  const [username,setUsername]=useState('');
  const [currentPassword,setCurrentPassword]=useState('');
  const [password,setPassword]=useState('');
  const [error,setError]=useState('');
  const [notice,setNotice]=useState('');
  const [busy,setBusy]=useState(false);
  async function save(e:FormEvent){e.preventDefault();setBusy(true);setError('');setNotice('');try{const result=await api<{username:string}>('/api/admin/account',{method:'POST',body:JSON.stringify({username:username.trim(),currentPassword,password})});setNotice(`管理员账户已更新：${result.username}`);setCurrentPassword('');setPassword('');}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  return <form className="settings-form" onSubmit={save}><div className="panel-heading"><div><h2>管理员账户</h2><p>用户名与密码保存在数据库，修改后立即生效。</p></div></div>
    <label>管理员用户名<input autoComplete="off" value={username} onChange={e=>setUsername(e.target.value)} placeholder="留空表示不修改用户名"/></label>
    <label>当前密码<input type="password" autoComplete="current-password" required value={currentPassword} onChange={e=>setCurrentPassword(e.target.value)} placeholder="验证身份，必填"/></label>
    <label>新密码（可选）<input type="password" autoComplete="new-password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="6 到 128 位，留空表示不修改密码"/></label>
    {error&&<div className="admin-error" role="alert">{error}</div>}
    {notice&&<div className="admin-success"><Check size={16}/>{notice}</div>}
    <div className="settings-actions"><button className="button" disabled={busy}>{busy?'正在保存…':'更新管理员账户'}<Check size={15}/></button></div>
  </form>;
}
function SettingsPage({section}:{section:SettingKey}){const meta=settingMeta[section];const [data,setData]=useState<Record<string,any>>({});const [error,setError]=useState('');const [notice,setNotice]=useState('');const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);useEffect(()=>{setLoading(true);api<{settings:Record<string,any>}>(`/api/admin/settings/${section}`).then(x=>setData(x.settings||{})).catch(e=>setError(e.message)).finally(()=>setLoading(false));},[section]);function change(key:string,value:any){setData(x=>({...x,[key]:value}));}async function save(e:FormEvent){e.preventDefault();setBusy(true);setError('');setNotice('');try{await api(`/api/admin/settings/${section}`,{method:'PUT',body:JSON.stringify(data)});setNotice('设置已保存');}catch(e){setError((e as Error).message)}finally{setBusy(false)}}return <><Heading title={meta.title} desc={meta.desc}/><ErrorBanner>{error}</ErrorBanner>{notice&&<div className="admin-success"><Check size={16}/>{notice}</div>}<div className="settings-layout"><nav className="settings-nav">{meta.links.map(([label,to])=><NavLink end={to==='/settings'} key={to} to={to}>{label}<ChevronRight size={15}/></NavLink>)}</nav><Panel title={meta.title} subtitle="修改后记得保存设置" className="settings-panel">{loading?<Loading/>:<form className="settings-form" onSubmit={save}>{section==='store'&&<><label>店铺名称<input value={data.name||''} onChange={e=>change('name',e.target.value)}/></label><label>客服电话<input value={data.phone||''} onChange={e=>change('phone',e.target.value)}/></label><label>客服时间<input value={data.hours||''} onChange={e=>change('hours',e.target.value)}/></label><label>商城公告<textarea rows={4} value={data.announcement||''} onChange={e=>change('announcement',e.target.value)}/></label><div className="switch-row"><span><b>店铺营业状态</b><small>关闭后前台仍展示商品，但无法下单提示会由运营配置。</small></span><select value={data.status||'open'} onChange={e=>change('status',e.target.value)}><option value="open">营业中</option><option value="closed">暂停营业</option></select></div></>}{section==='payment'&&<><div className="settings-callout"><CreditCard/><div><b>本地演示支付</b><p>当前没有连接真实支付渠道。这里仅保存支付方式展示偏好，不会收取真实款项。</p></div></div><Toggle label="显示支付宝" hint="商城前台可展示支付宝支付选项" checked={Boolean(data.alipay)} onChange={v=>change('alipay',v)}/><Toggle label="显示微信支付" hint="商城前台可展示微信支付选项" checked={Boolean(data.wechat)} onChange={v=>change('wechat',v)}/><label>待支付订单超时（分钟）<input type="number" min="1" max="1440" value={data.timeoutMinutes??15} onChange={e=>change('timeoutMinutes',Number(e.target.value))}/></label><label>最低订单金额（分）<input type="number" min="0" value={data.minimumCents??0} onChange={e=>change('minimumCents',Number(e.target.value))}/></label></>}{section==='shipping'&&<><label>自动发货模式<select value={data.mode||'auto'} onChange={e=>change('mode',e.target.value)}><option value="auto">支付后自动发货</option><option value="manual">全部手动处理</option></select></label><label>自动发货失败时<select value={data.failure||'queue'} onChange={e=>change('failure',e.target.value)}><option value="queue">放入待发货队列</option><option value="hold">暂停订单并联系客户</option></select></label><label>低库存提醒阈值<input type="number" min="0" value={data.lowStock??10} onChange={e=>change('lowStock',Number(e.target.value))}/></label><label>发货通知文案<textarea rows={3} value={data.message||''} onChange={e=>change('message',e.target.value)}/></label></>}{section==='notifications'&&<><label>新订单通知方式<input value={data.newOrder||''} onChange={e=>change('newOrder',e.target.value)} placeholder="站内通知 + 短信"/></label><label>退款通知方式<input value={data.refund||''} onChange={e=>change('refund',e.target.value)}/></label><label>库存预警通知方式<input value={data.inventory||''} onChange={e=>change('inventory',e.target.value)}/></label><label>通知邮箱<input type="email" value={data.email||''} onChange={e=>change('email',e.target.value)}/></label><label>接收手机号<input type="tel" value={data.phone||''} onChange={e=>change('phone',e.target.value)}/></label></>}{section==='security'&&<><div className="settings-callout"><ShieldCheck/><div><b>管理员账户安全</b><p>管理员用户名与密码保存在数据库，密码使用 scrypt 加盐哈希存储（不可逆），后台会话使用 HttpOnly Cookie。可在下方直接修改。</p></div></div><AdminAccountPanel/><Toggle label="双重验证策略" hint="保存此开关作为店铺安全策略记录；邮箱验证服务需在生产环境接入。" checked={Boolean(data.twoFactor)} onChange={v=>change('twoFactor',v)}/><label>子账号管理规则<textarea rows={4} value={data.childAccountPolicy||''} onChange={e=>change('childAccountPolicy',e.target.value)} placeholder="描述运营人员可访问的权限范围"/></label></>}<div className="settings-actions"><button className="button" disabled={busy}>{busy?'保存中…':'保存设置'}<Check size={15}/></button></div></form>}</Panel></div></>}
function Toggle({label,hint,checked,onChange}:{label:string;hint:string;checked:boolean;onChange:(v:boolean)=>void}){return <label className="switch-row"><span><b>{label}</b><small>{hint}</small></span><input type="checkbox" checked={checked} onChange={e=>onChange(e.target.checked)}/></label>}
function NotFound(){return <div className="admin-panel admin-not-found"><b>页面没有找到</b><Link className="button" to="/">返回经营总览</Link></div>}
function AdminRoutes(){return <Routes><Route path="/login" element={<AdminLoginWithCredentials/>}/><Route path="/*" element={<AdminGuard/>}/></Routes>}
export default function AdminApp(){return <BrowserRouter basename="/admin"><AdminRoutes/></BrowserRouter>}
createRoot(document.getElementById('root')!).render(<StrictMode><AdminApp/></StrictMode>);
